glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv0;
out vec2 v_worldPos;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  v_worldPos = pos.xy;
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec2 uv0;
in vec2 v_worldPos;
uniform sampler2D cc_spriteTexture;
uniform sampler2D maskTexture;
layout(std140) uniform SHADOWCOLOR {
  vec4 shadowColor;
};
#if !USE_ALPHA_TEST
  layout(std140) uniform ALPHA_THRESHOLD {
    float alphaThreshold;
  };
#endif
layout(std140) uniform SHADOWMASK {
  vec4 shadowCenter;
  vec4 shadowSize;
  float useMask;
};
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  o *= texture(cc_spriteTexture, uv0);
  ALPHA_TEST(o);
  float maskAlpha = 1.0;
  if (useMask > 0.5) {
      vec2 maskUV = (v_worldPos.xy - shadowCenter.xy) / shadowSize.xy;
      if (maskUV.x >= 0.0 && maskUV.x <= 1.0 &&
          maskUV.y >= 0.0 && maskUV.y <= 1.0) {
          maskAlpha = texture(maskTexture, maskUV).a;
      } else {
          maskAlpha = 0.0;
      }
  }
  o.a = o.a * shadowColor.a * maskAlpha;
  o.rgb = shadowColor.rgb;
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
#if USE_LOCAL
  uniform highp mat4 cc_matWorld;
#endif
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec2 uv0;
varying vec2 v_worldPos;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  v_worldPos = pos.xy;
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  return pos;
}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
#if USE_ALPHA_TEST
      uniform float alphaThreshold;
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
varying vec2 uv0;
varying vec2 v_worldPos;
uniform sampler2D cc_spriteTexture;
uniform sampler2D maskTexture;
uniform vec4 shadowColor;
#if !USE_ALPHA_TEST
  uniform float alphaThreshold;
#endif
uniform vec4 shadowCenter;
  uniform vec4 shadowSize;
  uniform float useMask;
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  o *= texture2D(cc_spriteTexture, uv0);
  ALPHA_TEST(o);
  float maskAlpha = 1.0;
  if (useMask > 0.5) {
      vec2 maskUV = (v_worldPos.xy - shadowCenter.xy) / shadowSize.xy;
      if (maskUV.x >= 0.0 && maskUV.x <= 1.0 &&
          maskUV.y >= 0.0 && maskUV.y <= 1.0) {
          maskAlpha = texture2D(maskTexture, maskUV).a;
      } else {
          maskAlpha = 0.0;
      }
  }
  o.a = o.a * shadowColor.a * maskAlpha;
  o.rgb = shadowColor.rgb;
  return o;
}
void main() { gl_FragColor = frag(); }
